    "weak": "弱",
    "decoder_note": "類型 7 使用公開已知的 26 位元組 XOR 金鑰。解碼是確定性且即時的——這說明了為什麼類型 7 無法提供真正的安全性。",
    "hash_input": "類型 7 雜湊",
    "plain_input": "明文密碼",
    "decode_btn": "解碼",
    "encode_btn": "編碼",
    "types": {
      "0": {
        "name": "明文",
        "severity": "嚴重",
        "desc": "沒有任何編碼。密碼以明文形式存儲並顯示在 running-config 和 startup-config 中。任何具有配置文件讀取權限或 TFTP/SNMP 備份權限的人都可以立即獲得憑據。",
        "secure": "對於用戶帳戶，請替換為 \"enable secret\"（類型 9 scrypt）或 \"username X secret 9 <hash>\"。"
      },
      "7": {
        "name": "維吉尼亞密碼",
        "severity": "高",
        "desc": "一種使用 26 字節硬編碼密鑰（公開文檔）的簡單可逆 XOR 加密。任何擁有散列值和此工具的網絡工程師都可以在幾毫秒內恢復明文。通過 \"service password-encryption\" 自動啟用——這只能防止肩窺，不能防止配置文件被盜。",
        "secure": "遷移到類型 8 (PBKDF2-SHA256) 或類型 9 (scrypt)。執行：\"username X secret 9 <hash>\" 和 \"enable secret 9 <hash>\"。"
      },
      "4": {
        "name": "SHA-256 (無鹽)",
        "severity": "中",
        "desc": "在 IOS 15.3(3) 中引入以替代類型 5 MD5，但幾乎立即被廢棄。它使用單輪 SHA-256，沒有鹽，也沒有密鑰拉伸，這使得它容易受到 GPU 加速的字典攻擊和彩虹表攻擊。思科官方建議從類型 4 遷移。",
        "secure": "替換為類型 8 (PBKDF2-SHA256, ~20,000 次迭代) 或類型 9 (scrypt)。兩者都使用了鹽，且破解的計算成本很高。"
      },
      "5": {
        "name": "MD5 (有鹽)",
        "severity": "可接受（傳統）",
        "desc": "有鹽 MD5（$1$ 格式）。與類型 0/7/4 的弱點 different——它經過加鹽 and 散列——但 MD5 在現代 GPU 上運行很快，這使得它對於弱密碼容易受到暴力破解。目前仍廣泛部署。目前可以接受，但應遷移到類型 8 或 9。",
        "secure": "升級到類型 8 或 9。類型 5 是可以接受의，但思科不再推薦用於新部署。"
      },
      "8": {
        "name": "PBKDF2-SHA-256",
        "severity": "強",
        "desc": "帶有 SHA-256 和約 20,000 次迭代的 PBKDF2。有鹽。破解的計算成本很高越。從 IOS 15.3(3) 開始支持。$8$ 格式。這是現代部署建議的最低類型。",
        "secure": "無需採取行動。繼續使用類型 8 或升級到類型 9。"
      },
      "9": {
        "name": "scrypt",
        "severity": "最佳",
        "desc": "N=16384, r=1, p=1 的 scrypt。內存密集型——對 GPU/ASIC 加速具有極強的抵抗力。$9$ 格式。從 IOS 15.3(3) 和 IOS-XE 16.x 開始支持。這是思科當前的最佳實踐建議。",
        "secure": "最佳實踐。無需採取行動。"
      }
    },
