    "sysctl_title": "Linux TCP 調優 (sysctl)",
    "sysctl_subtitle": "生成 sysctl 指令，根據您的路徑參數優化 Linux TCP 緩衝區和擁塞控制。",
    "sysctl_algo": "擁塞控制演算法",
    "sysctl_apply_hint": "應用指令：sysctl -p /etc/sysctl.d/99-tcp-tuning.conf。數值根據您的 BDP 計算。",
    "ref_title": "演算法參考",
    "ref_reno_desc": "經典的 AIMD 演算法。慢啟動在每个 RTT 將 cwnd 翻倍，直到達到 ssthresh. 擁塞避免每个 RTT 增加約 1 個段。收到 3 個冗餘 ACK 時：ssthresh = cwnd/2, cwnd = ssthresh。逾時時：cwnd = 1 MSS。公平但遺失後在高 BDP 路徑上利用率不足。",
    "ref_cubic_desc": "Linux 預設演算法。使用三次函數 W(t) = C(t-K)^3 + W_max (C=0.4, beta=0.7)。遺失後，cwnd 降至 W_max 的 70%，然後透過凹凸曲線增長。在長肥網路 (LFN) 上比 Reno 更激進。K = (W_max * 0.3 / C)^(1/3)。",
    "ref_bbr_desc": "Google 基於模型的演算法。不以遺失作為訊號，而是估算瓶頸頻寬和最小 RTT。階段：Startup (2.89x 增益)、Drain, ProbeBW (8 階段增益循環: 1.25/0.75/1...)、ProbeRTT (每 ~10 秒 4 個段)。即使有遺失也能達到滿吞吐量。",
