    "plat_f5": "F5 BIG-IP",
    "plat_huawei": "Huawei VRP",
    "plat_iosxe_notes": "請使用 \"show flash:\" 確認快閃檔案系統有足夠的可用空間。如果使用 SCP，必須在伺服器上設定 \"ip scp server enable\"，或裝置必須啟用 SSH 路由。",
    "plat_iosxr_notes": "IOS-XR 檔案系統使用 disk0: 或 disk1: 而非 flash:。XR 中的 SCP/SFTP 命令會互動式提示輸入使用者密碼。路由上下文（VRF）可以全域設定。",
    "plat_nxos_notes": "NX-OS 預設使用 bootflash:。請用 \"dir bootflash:\" 檢查檔案系統空間。VRF 必須能與伺服器進行 IP 通訊；請檢查預設路由或管理 VRF。",
    "plat_junos_notes": "Junos 上複製的檔案存放在 /var/tmp/ 或 /var/db/config/。請用 \"show system storage\" 檢查磁碟空間。TFTP 傳輸可能需要設定 Junos 路由協定，或使用 routing-instance 關鍵字。",
    "plat_eos_notes": "Arista 裝置使用 flash:。請用 \"dir flash:\" 驗證。為獲得高吞吐量，Arista 支援高度最佳化的原生 HTTP/HTTPS 複製。",
    "plat_fortios_notes": "FortiOS 的 TFTP 還原會取代開機映像並自動重新啟動裝置。請謹慎使用。務必事先儲存設定檔。",
    "plat_panos_notes": "Palo Alto PAN-OS 需要明確的 CLI 管理員權限才能執行軟體匯入命令。軟體也可以直接從 Palo Alto 官方支援更新下載。",
    "plat_linux_notes": "請檢查目標目錄的讀寫權限。確保已安裝用戶端（scp、curl）。透過 curl/wget 進行的 HTTP/HTTPS 傳輸可以高度並行化。",
    "plat_f5_notes": "請檢查 bigstart 程序和 F5 管理路由權限。目標資料夾 /shared/images/ 是 F5 ISO 檔案的預設位置。",
    "cmd_iosxe": "! Cisco IOS/IOS-XE 命令",
