    "explanation_title": "瞭解 NAT 與 PAT",
    "explanation_intro": "網路地址轉換 (NAT) 和埠地址轉換 (PAT) 是將一個 IP 地址空間映射到另一個空間的技術，主要用於節省有限的公網 IPv4 地址或解決子網衝突。",
    "nat_expl_title": "1. 什麼是 NAT？",
    "nat_expl_desc": "NAT 以 1 對 1 的方式轉換 IP 地址。它可以是靜態的（將一個私有 IP 永久映射到一個公網 IP，適合面向公網的伺服器）或動態的（根據需求從池中為私有主機分配公网 IP。一旦公網 IP 分配完畢，後續主機將被阻塞直到 IP 釋放）。埠號不被修改。",
    "pat_expl_title": "2. 什麼是 PAT (NAT 過載)？",
    "pat_expl_desc": "PAT (或埠地址轉換 / NAT Overload) 以多對一 (N 對 1) 的方式轉換 IP 地址和源埠號。多個私有主機通過分配唯一的源埠共享單個公網 IP 地址（例如 192.168.1.10:5000 和 192.168.1.11:5000 映射到 203.0.113.10:1024 和 203.0.113.10:1025）。這是家庭路由器和企業網際網路存取的標準方法。",
    "comparison_table_title": "比較摘要",
