    "about_body": "iperf 是一种用于主动测量 IP 网络上可达到的最大带宽的工具。一台主机作为服务器（监听者）运行，另一台作为客户端连接，通过 TCP、UDP 或 SCTP 发送（或接收）流量，并报告吞吐量、抖动和丢包情况。iperf3（二进制名 iperf3）是具有 JSON 输出和反向/双向模式的现代重写版；iperf2（二进制名 iperf）支持多客户端，在 Wi-Fi 和组播测试方面更强大。两者在通信上不兼容 — 两端必须运行相同的版本。",
